-- Phase A / 4 of 11: students (mirrors `Student` in src/types/index.ts, plus the approval workflow).
-- Student data belongs to minors: no client role can read or write this table except the administrator (see 0008).

create table public.students (
  id uuid primary key default gen_random_uuid(),
  -- ANU-YYYY-NNNNN. Always generated by the trigger below; a supplied value is ignored. Immutable.
  reference_no text not null unique,
  school_id uuid not null references public.schools (id) on delete restrict,

  name text not null check (char_length(btrim(name)) between 1 and 60 and name ~ '[[:alpha:]]' and name !~ '[0-9<>]'),
  father_name text not null check (char_length(btrim(father_name)) between 1 and 60 and father_name ~ '[[:alpha:]]' and father_name !~ '[0-9<>]'),
  mother_name text not null check (char_length(btrim(mother_name)) between 1 and 60 and mother_name ~ '[[:alpha:]]' and mother_name !~ '[0-9<>]'),
  dob date not null check (dob >= date '1980-01-01' and dob <= current_date),
  class_name text not null check (class_name in (
    'Nursery', 'LKG', 'UKG', 'Class 1', 'Class 2', 'Class 3', 'Class 4', 'Class 5', 'Class 6',
    'Class 7', 'Class 8', 'Class 9', 'Class 10', 'Class 11', 'Class 12', 'Other'
  )),
  -- Stored upper-case, like the app's normalisation (toStudentFields).
  section text not null check (section = upper(section) and char_length(section) between 1 and 5 and section ~ '^[A-Z0-9 ]+$'),
  roll_no text not null check (roll_no ~ '^[A-Za-z0-9/-]{1,10}$'),
  admission_no text not null check (admission_no ~ '^[A-Za-z0-9/-]{1,20}$'),
  address text not null check (char_length(btrim(address)) between 10 and 250),
  -- Bare 10-digit Indian mobile number; the app strips +91 / 0 before submitting.
  mobile text not null check (mobile ~ '^[6-9][0-9]{9}$'),

  -- Path inside the PRIVATE `student-photos` bucket. Never a URL. Null until a real upload exists.
  photo_path text check (photo_path is null or (char_length(photo_path) <= 300 and photo_path ~ '^[A-Za-z0-9/_.-]+$' and photo_path !~ '\.\.' and photo_path !~ '^/')),

  -- Optional details. The DB only blocks markup characters; the app's stricter character rules stay in zod.
  blood_group text check (blood_group is null or blood_group in ('A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-')),
  house_name text check (house_name is null or (char_length(house_name) between 1 and 40 and house_name !~ '[<>]')),
  house_colour text check (house_colour is null or (char_length(house_colour) between 1 and 30 and house_colour !~ '[<>]')),
  bus_route text check (bus_route is null or (char_length(bus_route) between 1 and 40 and bus_route !~ '[<>]')),
  bus_stoppage text check (bus_stoppage is null or (char_length(bus_stoppage) between 1 and 60 and bus_stoppage !~ '[<>]')),

  submitted_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),

  -- Soft archive, never delete. Null = not archived. (Replaces isArchived / archivedAt.)
  archived_at timestamptz,

  -- Approval workflow. Set server-side only: clients cannot write these columns (see 0008 grants).
  approval_status public.student_approval_status not null default 'pending',
  reviewed_at timestamptz,
  constraint students_review_consistent check (
    (approval_status = 'pending' and reviewed_at is null) or (approval_status <> 'pending' and reviewed_at is not null)
  )
);
alter table public.students enable row level security;
revoke all on table public.students from anon, authenticated;

-- Indexes for the real admin filters (school, class, section, status, submission date) and search
-- (name, reference, admission, roll). Sort order is newest submission first.
create index students_school_idx on public.students (school_id);
create index students_class_idx on public.students (class_name);
create index students_section_idx on public.students (upper(section));
create index students_submitted_idx on public.students (submitted_at desc);
create index students_review_idx on public.students (approval_status);
create index students_active_idx on public.students (submitted_at desc) where archived_at is null;
create index students_admission_idx on public.students (school_id, lower(admission_no));
create index students_name_trgm on public.students using gin (name extensions.gin_trgm_ops);
create index students_reference_trgm on public.students using gin (reference_no extensions.gin_trgm_ops);
create index students_admission_trgm on public.students using gin (admission_no extensions.gin_trgm_ops);
create index students_roll_trgm on public.students using gin (roll_no extensions.gin_trgm_ops);

-- The reference number is generated here, never trusted from the caller.
create function private.students_before_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.reference_no := private.format_reference('ANU', nextval('private.student_reference_seq'), 5);
  return new;
end;
$$;
revoke all on function private.students_before_insert() from public;
create trigger students_before_insert before insert on public.students
  for each row execute function private.students_before_insert();

-- Reference number, school and submission time never change after creation.
create function private.students_guard_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.reference_no is distinct from old.reference_no
     or new.school_id is distinct from old.school_id
     or new.submitted_at is distinct from old.submitted_at then
    raise exception 'reference number, school and submission time cannot be changed' using errcode = '42501';
  end if;
  return new;
end;
$$;
revoke all on function private.students_guard_update() from public;
create trigger students_guard_update before update on public.students
  for each row execute function private.students_guard_update();

-- Preserves today's rule exactly (mock StudentRepository.update): when the admission number is CHANGED, it must not
-- clash with another student of the same school who is not archived. Not enforced on insert (parents may resubmit),
-- and an unchanged number is never re-checked, so existing duplicates stay editable.
-- ASSUMPTION: a rejected submission does not count as a clash. See docs/supabase/decisions.md (D-ADM).
create function private.students_check_admission_on_change()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if lower(btrim(new.admission_no)) is distinct from lower(btrim(old.admission_no)) and exists (
    select 1 from public.students s
    where s.id <> new.id
      and s.school_id = new.school_id
      and s.archived_at is null
      and s.approval_status <> 'rejected'
      and lower(btrim(s.admission_no)) = lower(btrim(new.admission_no))
  ) then
    raise exception 'duplicate_admission_no' using errcode = '23505',
      detail = 'Another student of this school already uses this admission number.';
  end if;
  return new;
end;
$$;
revoke all on function private.students_check_admission_on_change() from public;
create trigger students_check_admission before update of admission_no on public.students
  for each row execute function private.students_check_admission_on_change();

create trigger students_touch_updated_at before update on public.students
  for each row execute function private.touch_updated_at();
